    'recipe_arros-tres-delicies_steps': ['Hierve el arroz y refréscalo con agua fría.', 'Sofríe la zanahoria en dados y el bacón.', 'Añade el arroz, los huevos batidos y remueve hasta que cuaje.'],
    'recipe_risotto-marisc_name': 'Risotto de marisco',
    'recipe_risotto-marisc_steps': ['Sofríe la cebolla y las gambas.', 'Añade el arroz y ve vertiendo caldo de pescado poco a poco.', 'Cuece 18 minutos con el azafrán hasta que esté cremoso.'],
    // ===== Receptes · primer (Pas 4, sub-lot 2) =====
    'recipe_amanida-verda_name': 'Ensalada verde',
    'recipe_amanida-verda_steps': ['Lava y corta la lechuga, el tomate y el pepino.', 'Mézclalo todo en una ensaladera.', 'Aliña con aceite, sal y unas olivas.'],
    'recipe_amanida-russa_name': 'Ensaladilla rusa',
    'recipe_amanida-russa_steps': ['Hierve las patatas, las zanahorias y los huevos hasta que estén tiernos.', 'Pélalo todo y córtalo en dados pequeños.', 'Mézclalo con la mayonesa y decora con olivas.'],
    'recipe_amanida-cesar_name': 'Ensalada césar',
    'recipe_amanida-cesar_steps': ['Cocina el pollo a la plancha y córtalo en tiras.', 'Lava y trocea la lechuga.', 'Mézclalo con el queso y los picatostes de pan.'],
    'recipe_amanida-grega_name': 'Ensalada griega',
    'recipe_amanida-grega_steps': ['Corta los tomates y el pepino en dados.', 'Añade el feta en dados y las olivas.', 'Aliña con aceite, sal y orégano si tienes.'],
    'recipe_sopa-verdures_name': 'Sopa de verduras',
    'recipe_sopa-verdures_steps': ['Sofríe la cebolla picada en una olla con un poco de aceite.', 'Añade las demás verduras cortadas y cubre con agua.', 'Hierve a fuego medio 25 minutos y salpimienta al gusto.'],
    'recipe_sopa-juliana_name': 'Sopa juliana',
    'recipe_sopa-juliana_steps': ['Corta todas las verduras en tiras finas (juliana).', 'Ponlo en la olla con agua y sal.', 'Hierve 30 minutos a fuego medio.'],
    'recipe_crema-carbasso_name': 'Crema de calabacín',
    'recipe_crema-carbasso_steps': ['Sofríe la cebolla y el calabacín cortados.', 'Cubre con agua y hierve 20 min hasta que esté tierno.', 'Tritúralo con la leche hasta obtener una crema fina.'],
    'recipe_crema-patata-porro_name': 'Crema de patata y puerro',
    'recipe_crema-patata-porro_steps': ['Sofríe los puerros cortados finamente.', 'Añade las patatas en dados y cubre con agua.', 'Hierve 25 min y tritura con la leche hasta hacer una crema.'],
    'recipe_gaspatxo_name': 'Gazpacho',
    'recipe_gaspatxo_steps': ['Pela los tomates y el pepino.', 'Tritúralo todo con el pimiento, la cebolla, aceite y sal.', 'Refrigera como mínimo 1 h y sirve bien frío.'],
    'recipe_vichyssoise_name': 'Vichyssoise',
    'recipe_vichyssoise_steps': ['Sofríe los puerros cortados finamente.', 'Cubre con agua, añade las patatas y hierve 20 min.', 'Tritura con la nata y enfría antes de servir.'],
    'recipe_amanida-pasta_name': 'Ensalada de pasta',
    'recipe_amanida-pasta_steps': ['Hierve la pasta y refréscala con agua fría.', 'Corta el tomate y el queso en dados.', 'Mézclalo todo con las olivas y un hilo de aceite.'],
    'recipe_amanida-tonyina_name': 'Ensalada de atún',
    'recipe_amanida-tonyina_steps': ['Lava y trocea la lechuga.', 'Corta el tomate en cuartos.', 'Añade el atún escurrido y aliña con aceite.'],
    'recipe_tomaquets-formatge_name': 'Tomates con queso',
    'recipe_tomaquets-formatge_steps': ['Corta los tomates en rodajas gruesas.', 'Altérnalas con lonchas de queso en el plato.', 'Decora con albahaca, aceite y sal.'],
    'recipe_amanida-llenties_name': 'Ensalada de lentejas',
    'recipe_amanida-llenties_steps': ['Escurre las lentejas (mejor si ya están cocidas).', 'Corta la cebolla y la zanahoria muy pequeñas.', 'Mézclalo todo y aliña con aceite y sal.'],
    'recipe_escalivada_name': 'Escalivada',
    'recipe_escalivada_steps': ['Pon las verduras enteras en el horno a 200°.', 'Cuécelas 45 minutos dándoles la vuelta a mitad.', 'Pélalas, córtalas en tiras y aliña con aceite y sal.'],
    // ===== Receptes · esmorzar (Pas 4, sub-lot 1) =====
    'recipe_pa-tomaquet_name': 'Pan con tomate',
    'recipe_pa-tomaquet_steps': ['Corta el pan en rebanadas y, si quieres, tuéstalas ligeramente.', 'Restriega medio tomate maduro sobre cada rebanada.', 'Termina con un chorrito de aceite y una pizca de sal.'],
    'recipe_pa-tomaquet_tip': 'El tomate de colgar es el más tradicional.',
    'recipe_truita-francesa_name': 'Tortilla francesa',
    'recipe_truita-francesa_steps': ['Bate los huevos con un poco de sal (y un chorrito de leche si quieres).', 'Funde la mantequilla en una sartén antiadherente.', 'Vierte los huevos y, cuando cuaje por debajo, dobla la tortilla.'],
    'recipe_iogurt-fruita_name': 'Yogur con fruta',
    'recipe_iogurt-fruita_steps': ['Vierte el yogur en el bol.', 'Lava y corta la fruta en trozos pequeños.', 'Reparte la fruta por encima y termina con un hilo de miel.'],
    'recipe_biquini_name': 'Sándwich mixto',
    'recipe_biquini_steps': ['Pon jamón dulce y queso entre las dos rebanadas de pan.', 'Unta ligeramente la parte exterior con mantequilla.', 'Cocínalo a la plancha hasta que el queso se funda.'],
    'recipe_pa-mantega-melmelada_name': 'Pan con mantequilla y mermelada',
    'recipe_pa-mantega-melmelada_steps': ['Tuesta el pan hasta que esté dorado.', 'Unta la mantequilla cuando aún está caliente.', 'Extiende la mermelada por encima.'],
    'recipe_cereals-llet_name': 'Cereales con leche',
    'recipe_cereals-llet_steps': ['Pon los cereales en el bol.', 'Vierte la leche bien fría por encima.', 'Si quieres, termina con un hilo de miel.'],
    'recipe_avena-fruita_name': 'Avena con fruta',
    'recipe_avena-fruita_steps': ['Cocina la avena con la leche a fuego bajo 4-5 min removiendo.', 'Corta el plátano en rodajas.', 'Viértelo en el bol y termina con un hilo de miel.'],
    'recipe_torrada-alvocat_name': 'Tostada con aguacate',
    'recipe_torrada-alvocat_steps': ['Tuesta la rebanada de pan.', 'Aplasta el aguacate con un tenedor.', 'Extiéndelo sobre el pan y sazona con sal y pimienta.'],
    'recipe_smoothie-platan_name': 'Smoothie de plátano',
    'recipe_smoothie-platan_steps': ['Pela el plátano y ponlo en el vaso de la batidora.', 'Vierte la leche y la miel.', 'Tritura hasta que quede cremoso.'],
    'recipe_pancakes_name': 'Tortitas',
    'recipe_pancakes_steps': ['Mezcla los huevos, la leche y la harina hasta formar una masa.', 'Cocina pequeñas porciones en la sartén con un poco de mantequilla.', 'Dales la vuelta cuando hagan burbujas y apílalas con miel.'],
    'recipe_pa-formatge_name': 'Pan con queso',
    'recipe_pa-formatge_steps': ['Corta el pan en rebanadas.', 'Pon una loncha de queso sobre cada una.', 'Termina con un hilo de aceite si quieres.'],
    'recipe_iogurt-mel-fruits-secs_name': 'Yogur con miel y frutos secos',
    'recipe_iogurt-mel-fruits-secs_steps': ['Vierte el yogur en el bol.', 'Añade la miel.', 'Decora con frutos secos troceados.'],
    'recipe_torrada-francesa_name': 'Torrija',
    'recipe_torrada-francesa_steps': ['Bate el huevo con la leche en un bol.', 'Moja bien las rebanadas de pan.', 'Cocínalas en la sartén con mantequilla hasta que se doren por ambos lados.'],
    'recipe_cuixot-formatge_name': 'Jamón dulce con queso',
    'recipe_cuixot-formatge_steps': ['Coloca el jamón dulce en el plato.', 'Acompáñalo con el queso cortado.', 'Sirve con pan si quieres hacer un bocadillo.'],
    'recipe_macedonia-matinera_name': 'Macedonia matutina',
    'recipe_macedonia-matinera_steps': ['Pela las frutas y córtalas en dados pequeños.', 'Mézclalas en un bol grande.', 'Vierte el zumo de una naranja para macerarlas.'],
