    // Textos llargs (A)
    calcExplanationMoney: 'Para cada producto calculamos el precio y el peso totales según lo que hayas puesto:\n\n• Si pones cantidad y peso, el peso es por unidad (3 briks × 500ml = 1,5L).\n• Si pones solo cantidad, multiplicamos por el peso medio según el emoji.\n• Si pones solo peso/volumen, es el total.\n• Si no pones nada, usamos valores medios.\n\nPara el precio:\n• Si has puesto precio y tienes más de una unidad, es el precio por unidad.\n• Si no has puesto precio, usamos el precio medio por kg de la categoría.\n\nCuando dices «me lo he comido al 50%», lo aprovechado es el 50% del valor total. Cuando dices «lo he tirado al 100%», lo tirado es el 100% del valor.',
    calcExplanationCO2: 'El peso total se calcula igual que para el precio (mira la pestaña de dinero):\n\n• Cantidad + peso = peso por unidad × cantidad.\n• Solo cantidad = cantidad × peso medio según el emoji.\n• Solo peso/volumen = total directo.\n\nDespués multiplicamos el peso total por la emisión media de la categoría (por ejemplo, la carne roja ~27 kg de CO₂ por kg) y por el % consumido o tirado.\n\nEl CO₂ evitado cuenta lo que te has comido. El CO₂ desperdiciado cuenta lo que has tirado: la emisión ya ocurrió igualmente.',
    infoCalcMoneySections: [
      {
        emoji: '📦',
        title: 'El peso total',
        intro: 'Calculamos el peso según lo que hayas puesto:',
        bullets: [
          'Cantidad + peso → es por unidad (3 briks × 500 ml = 1,5 L)',
          'Solo cantidad → multiplicamos por el peso medio según el emoji',
          'Solo peso/volumen → es el total',
          'Nada → usamos valores medios'
        ]
      },
      {
        emoji: '💰',
        title: 'El precio total',
        bullets: [
          'Si has puesto precio y tienes más de una unidad → es por unidad',
          'Si no has puesto precio → precio medio por kg de la categoría'
        ]
      },
      {
        emoji: '📊',
        title: 'El cálculo final',
        bullets: [
          'Aprovechado = precio total × % consumido',
          'Tirado = precio total × % tirado'
        ]
      },
      {
        emoji: '💡',
        title: 'Ejemplo',
        example: 'Leche 1 L · precio 1,20€\nHas bebido el 50% → 0,60€ aprovechado'
      }
    ],
    infoCalcCo2Sections: [
      {
        emoji: '📦',
        title: 'El peso total',
        intro: 'Igual que en el dinero:',
        bullets: [
          'Cantidad + peso = peso por unidad × cantidad',
          'Solo cantidad = cantidad × peso medio según el emoji',
          'Solo peso/volumen = el total directo'
        ]
      },
      {
        emoji: '🌱',
        title: 'La emisión por categoría',
        intro: 'Cada categoría tiene una emisión media por kg:',
        bullets: [
          'Carne roja ≈ 27 kg CO₂/kg',
          'Lácteos ≈ 3 kg CO₂/kg',
          'Verdura ≈ 0,5 kg CO₂/kg'
        ]
      },
      {
        emoji: '📊',
        title: 'El cálculo final',
        bullets: [
          'CO₂ evitado = peso × emisión × % consumido',
          'CO₂ desperdiciado = peso × emisión × % tirado (la emisión ya ocurrió)'
        ]
      },
      {
        emoji: '💡',
        title: 'Ejemplo',
        example: '500 g de carne roja tirados\n0,5 × 27 = 13,5 kg CO₂ desperdiciados'
      }
    ],
