    // ===== Suggeriments / patterns.js (Front B, Pas 3) =====
    patFreqTrashedDesc: (name, count) => "You've thrown away " + name + ' ' + count + ' times this month. ' + (count >= 5 ? "We'd suggest buying less, or a reminder before it expires." : 'Buy less or adjust the amount.'),
    patFreqTrashedAction: 'Turn on a 4-day alert',
