    configureNotif: 'Set up notifications',
    // Textos llargs (A)
    calcExplanationMoney: 'For each product we work out the total price and weight from what you entered:\n\n• If you enter quantity and weight, the weight is per unit (3 cartons × 500ml = 1.5L).\n• If you enter quantity only, we multiply by the average weight for the emoji.\n• If you enter weight/volume only, that\'s the total.\n• If you enter nothing, we use average values.\n\nFor the price:\n• If you entered a price and have more than one unit, it\'s the price per unit.\n• If you entered no price, we use the average price per kg for the category.\n\nWhen you say "I ate 50% of it", the amount used is 50% of the total value. When you say "I threw away 100%", the amount wasted is 100% of the value.',
    calcExplanationCO2: 'The total weight is worked out the same way as for the price (see the money tab):\n\n• Quantity + weight = weight per unit × quantity.\n• Quantity only = quantity × average weight for the emoji.\n• Weight/volume only = the total directly.\n\nThen we multiply the total weight by the category\'s average emissions (for example, red meat ~27 kg of CO₂ per kg) and by the % consumed or thrown away.\n\nCO₂ avoided counts what you ate. CO₂ wasted counts what you threw away — the emissions happened anyway.',
    infoCalcMoneySections: [
      {
        emoji: '📦',
        title: 'The total weight',
        intro: 'We work out the weight from what you entered:',
        bullets: [
          'Quantity + weight → it\'s per unit (3 cartons × 500 ml = 1.5 L)',
          'Quantity only → we multiply by the average weight for the emoji',
          'Weight/volume only → that\'s the total',
          'Nothing → we use average values'
        ]
      },
      {
        emoji: '💰',
        title: 'The total price',
        bullets: [
          'If you entered a price and have more than one unit → it\'s per unit',
          'If you entered no price → average price per kg for the category'
        ]
      },
      {
        emoji: '📊',
        title: 'The final calculation',
        bullets: [
          'Used = total price × % consumed',
          'Wasted = total price × % wasted'
        ]
      },
      {
        emoji: '💡',
        title: 'Example',
        example: 'Milk 1 L · price €1.20\nYou drank 50% → €0.60 used'
      }
    ],
    infoCalcCo2Sections: [
      {
        emoji: '📦',
        title: 'The total weight',
        intro: 'Same as for money:',
        bullets: [
          'Quantity + weight = weight per unit × quantity',
          'Quantity only = quantity × average weight for the emoji',
          'Weight/volume only = the total directly'
        ]
      },
      {
        emoji: '🌱',
        title: 'Emissions per category',
        intro: 'Each category has an average emission per kg:',
        bullets: [
          'Red meat ≈ 27 kg CO₂/kg',
          'Dairy ≈ 3 kg CO₂/kg',
          'Vegetables ≈ 0.5 kg CO₂/kg'
        ]
      },
      {
        emoji: '📊',
        title: 'The final calculation',
        bullets: [
          'CO₂ avoided = weight × emissions × % consumed',
          'CO₂ wasted = weight × emissions × % wasted (the emissions already happened)'
        ]
      },
      {
        emoji: '💡',
        title: 'Example',
        example: '500 g of red meat thrown away\n0.5 × 27 = 13.5 kg CO₂ wasted'
      }
    ],
