    'recipe_espaguetis-carbonara_name': 'Spaghettis carbonara',
    'recipe_espaguetis-carbonara_steps': ['Fais cuire les spaghettis et réserve un peu de leur eau.', "Fais revenir le lard coupé jusqu'à ce qu'il soit croustillant.", 'Éteins le feu, mélange avec les pâtes, les jaunes battus et le fromage.'],
    'recipe_espaguetis-carbonara_tip': 'Ne mets jamais les œufs sur le feu allumé — ils coaguleraient.',
    'recipe_espaguetis-bolonyesa_name': 'Spaghettis à la bolognaise',
    'recipe_espaguetis-bolonyesa_steps': ["Fais revenir l'oignon haché et ajoute la viande jusqu'à ce qu'elle soit dorée.", 'Verse la tomate et laisse cuire à feu doux 20 min.', 'Fais cuire les spaghettis et sers avec la sauce par-dessus.'],
    'recipe_macarrons-napolitana_name': 'Macaronis à la napolitaine',
    'recipe_macarrons-napolitana_steps': ['Fais cuire les macaronis al dente.', 'Fais chauffer la tomate dans une poêle.', 'Mélange les pâtes avec la sauce et râpe du fromage par-dessus.'],
    'recipe_pasta-pesto_name': 'Pâtes au pesto',
    'recipe_pasta-pesto_steps': ["Mixe le basilic avec le fromage, les pignons et l'huile.", 'Fais cuire les pâtes et égoutte-les.', 'Mélange-les avec le pesto hors du feu.'],
    'recipe_lasanya_name': 'Lasagnes',
