    'recipe_risotto-bolets_name': 'Risotto aux champignons',
    'recipe_risotto-bolets_steps': ["Fais revenir l'oignon et les champignons coupés.", 'Ajoute le riz et verse peu à peu du bouillon chaud pendant 18 min.', 'Termine avec le fromage râpé hors du feu.'],
    'recipe_arros-verdures_name': 'Riz aux légumes',
    'recipe_arros-verdures_steps': ["Fais revenir l'oignon et les légumes coupés.", "Ajoute le riz et le double d'eau salée.", 'Laisse cuire à couvert 18 minutes à feu doux.'],
    'recipe_paella-mixta_name': 'Paella mixte',
    'recipe_paella-mixta_steps': ["Fais dorer le poulet dans la poêle à paella avec un peu d'huile.", 'Fais revenir le poivron et la tomate, puis ajoute le riz.', 'Couvre de bouillon, ajoute les gambas et laisse cuire 18 min sans remuer.'],
    'recipe_fideua_name': 'Fideuà',
