    'recipe_amanida-verda_steps': ['Lave et coupe la laitue, la tomate et le concombre.', 'Mélange le tout dans un saladier.', "Assaisonne avec de l'huile, du sel et quelques olives."],
    'recipe_amanida-russa_name': 'Salade russe',
    'recipe_amanida-russa_steps': ["Fais bouillir les pommes de terre, les carottes et les œufs jusqu'à ce qu'ils soient tendres.", 'Épluche le tout et coupe en petits dés.', 'Mélange avec la mayonnaise et décore avec des olives.'],
    'recipe_amanida-cesar_name': 'Salade César',
    'recipe_amanida-cesar_steps': ['Fais cuire le poulet à la plancha et coupe-le en lanières.', 'Lave et découpe la laitue.', 'Mélange avec le fromage et les croûtons de pain.'],
    'recipe_amanida-grega_name': 'Salade grecque',
    'recipe_amanida-grega_steps': ['Coupe les tomates et le concombre en dés.', 'Ajoute la feta en dés et les olives.', "Assaisonne avec de l'huile, du sel et de l'origan si tu en as."],
    'recipe_sopa-verdures_name': 'Soupe de légumes',
    'recipe_sopa-verdures_steps': ["Fais revenir l'oignon haché dans une casserole avec un peu d'huile.", "Ajoute les autres légumes coupés et couvre d'eau.", 'Fais bouillir à feu moyen 25 minutes et sale et poivre à ton goût.'],
    'recipe_sopa-juliana_name': 'Soupe julienne',
    'recipe_sopa-juliana_steps': ['Coupe tous les légumes en fines lanières (julienne).', "Mets le tout dans la casserole avec de l'eau et du sel.", 'Fais bouillir 30 minutes à feu moyen.'],
    'recipe_crema-carbasso_name': 'Velouté de courgette',
    'recipe_crema-carbasso_steps': ["Fais revenir l'oignon et la courgette coupés.", "Couvre d'eau et fais bouillir 20 min jusqu'à ce que ce soit tendre.", "Mixe le tout avec le lait jusqu'à obtenir un velouté lisse."],
    'recipe_crema-patata-porro_name': 'Velouté pomme de terre-poireau',
    'recipe_crema-patata-porro_steps': ['Fais revenir les poireaux coupés finement.', "Ajoute les pommes de terre en dés et couvre d'eau.", 'Fais bouillir 25 min et mixe avec le lait pour obtenir un velouté.'],
    'recipe_gaspatxo_name': 'Gaspacho',
    'recipe_gaspatxo_steps': ['Épluche les tomates et le concombre.', "Mixe le tout avec le poivron, l'oignon, l'huile et le sel.", 'Réfrigère au moins 1 h et sers bien frais.'],
    'recipe_vichyssoise_name': 'Vichyssoise',
    'recipe_vichyssoise_steps': ['Fais revenir les poireaux coupés finement.', "Couvre d'eau, ajoute les pommes de terre et fais bouillir 20 min.", 'Mixe avec la crème et laisse refroidir avant de servir.'],
    'recipe_amanida-pasta_name': 'Salade de pâtes',
    'recipe_amanida-pasta_steps': ["Fais bouillir les pâtes et rafraîchis-les à l'eau froide.", 'Coupe la tomate et le fromage en dés.', "Mélange le tout avec les olives et un filet d'huile."],
    'recipe_amanida-tonyina_name': 'Salade de thon',
    'recipe_amanida-tonyina_steps': ['Lave et découpe la laitue.', 'Coupe la tomate en quartiers.', "Ajoute le thon égoutté et assaisonne avec de l'huile."],
    'recipe_tomaquets-formatge_name': 'Tomates au fromage',
    'recipe_tomaquets-formatge_steps': ['Coupe les tomates en tranches épaisses.', "Alterne-les avec des tranches de fromage dans l'assiette.", "Décore avec du basilic, de l'huile et du sel."],
    'recipe_amanida-llenties_name': 'Salade de lentilles',
    'recipe_amanida-llenties_steps': ['Égoutte les lentilles (de préférence déjà cuites).', "Coupe l'oignon et la carotte très finement.", "Mélange le tout et assaisonne avec de l'huile et du sel."],
    'recipe_escalivada_name': 'Escalivada',
    'recipe_escalivada_steps': ['Mets les légumes entiers au four à 200°.', 'Fais-les cuire 45 minutes en les retournant à mi-cuisson.', "Épluche-les, coupe-les en lanières et assaisonne avec de l'huile et du sel."],
    // ===== Receptes · esmorzar (Pas 4, sub-lot 1) =====
    'recipe_pa-tomaquet_name': 'Pain à la tomate',
    'recipe_pa-tomaquet_steps': ['Coupe le pain en tranches et, si tu veux, fais-les griller légèrement.', 'Frotte une demi-tomate mûre sur chaque tranche.', "Termine avec un filet d'huile et une pincée de sel."],
    'recipe_pa-tomaquet_tip': 'La tomate de garde est la plus traditionnelle.',
    'recipe_truita-francesa_name': 'Omelette nature',
    'recipe_truita-francesa_steps': ['Bats les œufs avec un peu de sel (et un filet de lait si tu veux).', 'Fais fondre le beurre dans une poêle antiadhésive.', "Verse les œufs et, quand le dessous est pris, plie l'omelette."],
    'recipe_iogurt-fruita_name': 'Yaourt aux fruits',
    'recipe_iogurt-fruita_steps': ['Verse le yaourt dans le bol.', 'Lave et coupe les fruits en petits morceaux.', 'Répartis les fruits par-dessus et termine avec un filet de miel.'],
    'recipe_biquini_name': 'Croque-monsieur',
    'recipe_biquini_steps': ['Mets le jambon et le fromage entre les deux tranches de pain.', "Étale un peu de beurre sur l'extérieur.", "Fais-le cuire à la plancha jusqu'à ce que le fromage fonde."],
    'recipe_pa-mantega-melmelada_name': 'Pain beurre-confiture',
    'recipe_pa-mantega-melmelada_steps': ["Fais griller le pain jusqu'à ce qu'il soit doré.", "Étale le beurre pendant qu'il est encore chaud.", 'Étale la confiture par-dessus.'],
    'recipe_cereals-llet_name': 'Céréales au lait',
    'recipe_cereals-llet_steps': ['Mets les céréales dans le bol.', 'Verse le lait bien froid par-dessus.', 'Si tu veux, termine avec un filet de miel.'],
    'recipe_avena-fruita_name': "Flocons d'avoine aux fruits",
    'recipe_avena-fruita_steps': ["Fais cuire les flocons d'avoine avec le lait à feu doux 4-5 min en remuant.", 'Coupe la banane en rondelles.', 'Verse le tout dans le bol et termine avec un filet de miel.'],
    'recipe_torrada-alvocat_name': "Toast à l'avocat",
    'recipe_torrada-alvocat_steps': ['Fais griller la tranche de pain.', "Écrase l'avocat avec une fourchette.", 'Étale-le sur le pain et assaisonne avec du sel et du poivre.'],
    'recipe_smoothie-platan_name': 'Smoothie à la banane',
    'recipe_smoothie-platan_steps': ['Épluche la banane et mets-la dans le bol du blender.', 'Verse le lait et le miel.', "Mixe jusqu'à obtenir une texture crémeuse."],
    'recipe_pancakes_name': 'Pancakes',
    'recipe_pancakes_steps': ["Mélange les œufs, le lait et la farine jusqu'à obtenir une pâte.", 'Fais cuire de petites portions à la poêle avec un peu de beurre.', 'Retourne-les quand elles font des bulles et empile-les avec du miel.'],
    'recipe_pa-formatge_name': 'Pain au fromage',
    'recipe_pa-formatge_steps': ['Coupe le pain en tranches.', 'Pose une tranche de fromage sur chacune.', "Termine avec un filet d'huile si tu veux."],
    'recipe_iogurt-mel-fruits-secs_name': 'Yaourt au miel et fruits secs',
    'recipe_iogurt-mel-fruits-secs_steps': ['Verse le yaourt dans le bol.', 'Ajoute le miel.', 'Décore avec des fruits secs concassés.'],
    'recipe_torrada-francesa_name': 'Pain perdu',
    'recipe_torrada-francesa_steps': ["Bats l'œuf avec le lait dans un bol.", 'Trempe bien les tranches de pain.', "Fais-les cuire à la poêle avec du beurre jusqu'à ce qu'elles soient dorées des deux côtés."],
    'recipe_cuixot-formatge_name': 'Jambon-fromage',
    'recipe_cuixot-formatge_steps': ["Dispose le jambon dans l'assiette.", 'Accompagne-le du fromage coupé.', 'Sers avec du pain si tu veux en faire un sandwich.'],
    'recipe_macedonia-matinera_name': 'Salade de fruits du matin',
    'recipe_macedonia-matinera_steps': ['Épluche les fruits et coupe-les en petits dés.', 'Mélange-les dans un grand bol.', "Verse le jus d'une orange pour les faire macérer."],
