    // Textos llargs (A)
    calcExplanationMoney: 'Pour chaque produit, nous calculons le prix et le poids totaux selon ce que tu as indiqué :\n\n• Si tu indiques la quantité et le poids, le poids est par unité (3 briques × 500ml = 1,5L).\n• Si tu indiques seulement la quantité, on multiplie par le poids moyen selon l\'emoji.\n• Si tu indiques seulement le poids/volume, c\'est le total.\n• Si tu n\'indiques rien, on utilise des valeurs moyennes.\n\nPour le prix :\n• Si tu as indiqué un prix et as plus d\'une unité, c\'est le prix par unité.\n• Si tu n\'as pas indiqué de prix, on utilise le prix moyen au kg de la catégorie.\n\nQuand tu dis « j\'en ai mangé 50 % », la part utilisée est 50 % de la valeur totale. Quand tu dis « je l\'ai jeté à 100 % », la part gaspillée est 100 % de la valeur.',
    calcExplanationCO2: 'Le poids total se calcule comme pour le prix (regarde l\'onglet argent) :\n\n• Quantité + poids = poids par unité × quantité.\n• Quantité seule = quantité × poids moyen selon l\'emoji.\n• Poids/volume seul = total directement.\n\nEnsuite, on multiplie le poids total par l\'émission moyenne de la catégorie (par exemple, la viande rouge ~27 kg de CO₂ par kg) et par le % consommé ou jeté.\n\nLe CO₂ évité compte ce que tu as mangé. Le CO₂ gaspillé compte ce que tu as jeté — l\'émission a eu lieu de toute façon.',
    infoCalcMoneySections: [
      {
        emoji: '📦',
        title: 'Le poids total',
        intro: 'Nous calculons le poids selon ce que tu as indiqué :',
        bullets: [
          'Quantité + poids → c\'est par unité (3 briques × 500 ml = 1,5 L)',
          'Quantité seule → on multiplie par le poids moyen selon l\'emoji',
          'Poids/volume seul → c\'est le total',
          'Rien → on utilise des valeurs moyennes'
        ]
      },
      {
        emoji: '💰',
        title: 'Le prix total',
        bullets: [
          'Si tu as indiqué un prix et as plus d\'une unité → c\'est par unité',
          'Si tu n\'as pas indiqué de prix → prix moyen au kg de la catégorie'
        ]
      },
      {
        emoji: '📊',
        title: 'Le calcul final',
        bullets: [
          'Utilisé = prix total × % consommé',
          'Gaspillé = prix total × % gaspillé'
        ]
      },
      {
        emoji: '💡',
        title: 'Exemple',
        example: 'Lait 1 L · prix 1,20 €\nTu en as bu 50 % → 0,60 € utilisé'
      }
    ],
    infoCalcCo2Sections: [
      {
        emoji: '📦',
        title: 'Le poids total',
        intro: 'Comme pour l\'argent :',
        bullets: [
          'Quantité + poids = poids par unité × quantité',
          'Quantité seule = quantité × poids moyen selon l\'emoji',
          'Poids/volume seul = le total directement'
        ]
      },
      {
        emoji: '🌱',
        title: "L'émission par catégorie",
        intro: 'Chaque catégorie a une émission moyenne au kg :',
        bullets: [
          'Viande rouge ≈ 27 kg CO₂/kg',
          'Produits laitiers ≈ 3 kg CO₂/kg',
          'Légumes ≈ 0,5 kg CO₂/kg'
        ]
      },
      {
        emoji: '📊',
        title: 'Le calcul final',
        bullets: [
          'CO₂ évité = poids × émission × % consommé',
          'CO₂ gaspillé = poids × émission × % gaspillé (l\'émission a déjà eu lieu)'
        ]
      },
      {
        emoji: '💡',
        title: 'Exemple',
        example: '500 g de viande rouge jetés\n0,5 × 27 = 13,5 kg CO₂ gaspillés'
      }
    ],
